"""sklearn.utils.extmath — extended math helpers.

Pure numpy implementations matching upstream's API and behaviour."""

import numpy as _np


def safe_sparse_dot(a, b, *, dense_output=False):
    """Dot product that handles sparse-vs-dense combinations. The shim
    treats everything as dense numpy arrays."""
    a = _np.asarray(a) if not hasattr(a, 'toarray') else a.toarray()
    b = _np.asarray(b) if not hasattr(b, 'toarray') else b.toarray()
    return _np.dot(a, b)


def randomized_svd(M, n_components, *, n_oversamples=10, n_iter='auto',
                    power_iteration_normalizer='auto', transpose='auto',
                    flip_sign=True, random_state=None, svd_lapack_driver='gesdd'):
    """Truncated SVD via numpy's standard LAPACK. Returns
    ``(U, Sigma, Vt)`` matching the top ``n_components`` singular values."""
    M = _np.asarray(M, dtype=float)
    U, s, Vt = _np.linalg.svd(M, full_matrices=False)
    return U[:, :n_components], s[:n_components], Vt[:n_components]


def randomized_range_finder(A, *, size, n_iter, power_iteration_normalizer='auto',
                              random_state=None):
    """Sample a random matrix whose columns approximate the column space
    of A. Used internally by :func:`randomized_svd`."""
    rng = _np.random.default_rng(random_state if isinstance(random_state, int) else None)
    Q = rng.standard_normal((A.shape[1], size))
    for _ in range(n_iter):
        Q = A.T @ (A @ Q)
        Q, _ = _np.linalg.qr(Q)
    return A @ Q


def svd_flip(u, v, u_based_decision=True):
    """Flip signs to make the SVD deterministic."""
    if u_based_decision:
        max_abs_cols = _np.argmax(_np.abs(u), axis=0)
        signs = _np.sign(u[max_abs_cols, range(u.shape[1])])
    else:
        max_abs_rows = _np.argmax(_np.abs(v), axis=1)
        signs = _np.sign(v[range(v.shape[0]), max_abs_rows])
    return u * signs, v * signs[:, None]


def row_norms(X, squared=False):
    """Row-wise L2 norms."""
    X = _np.asarray(X)
    n = (X ** 2).sum(axis=1)
    return n if squared else _np.sqrt(n)


def softmax(X, copy=True):
    """Stable softmax along the last axis."""
    X = _np.asarray(X, dtype=float)
    if copy: X = X.copy()
    X -= X.max(axis=-1, keepdims=True)
    _np.exp(X, out=X)
    X /= X.sum(axis=-1, keepdims=True)
    return X


def log_logistic(X, out=None):
    """Compute log(1 / (1 + exp(-x))) in a numerically stable way."""
    X = _np.asarray(X, dtype=float)
    out = _np.empty_like(X) if out is None else out
    pos = X >= 0
    out[pos] = -_np.log1p(_np.exp(-X[pos]))
    out[~pos] = X[~pos] - _np.log1p(_np.exp(X[~pos]))
    return out


def squared_norm(x):
    """L2 norm squared of a flattened array."""
    x = _np.asarray(x)
    return float((x.ravel() ** 2).sum())


def weighted_mode(a, w, *, axis=0):
    """Most common value in ``a``, weighted by ``w``."""
    a = _np.asarray(a); w = _np.asarray(w)
    # For each unique value, sum its weights.
    if axis is None:
        a, w = a.ravel(), w.ravel()
        vals, inverse = _np.unique(a, return_inverse=True)
        weights = _np.bincount(inverse, weights=w)
        return vals[_np.argmax(weights)], weights.max()
    # General axis support — naive loop.
    results_mode = _np.empty(a.shape[:axis] + a.shape[axis+1:])
    results_count = _np.empty_like(results_mode)
    for idx in _np.ndindex(results_mode.shape):
        sl = list(idx); sl.insert(axis, slice(None))
        col_a, col_w = a[tuple(sl)], w[tuple(sl)]
        vals, inverse = _np.unique(col_a, return_inverse=True)
        weights = _np.bincount(inverse, weights=col_w)
        results_mode[idx] = vals[_np.argmax(weights)]
        results_count[idx] = weights.max()
    return results_mode, results_count


def cartesian(arrays, out=None):
    """Generate the Cartesian product of input arrays."""
    arrays = [_np.asarray(x) for x in arrays]
    n = _np.prod([x.size for x in arrays])
    if out is None:
        out = _np.zeros((n, len(arrays)), dtype=arrays[0].dtype)
    m = n // arrays[0].size
    out[:, 0] = _np.repeat(arrays[0], m)
    if len(arrays) > 1:
        cartesian(arrays[1:], out=out[:m, 1:])
        for j in range(1, arrays[0].size):
            out[j*m:(j+1)*m, 1:] = out[:m, 1:]
    return out


def density(w, **kwargs):
    """Fraction of non-zero entries in ``w``."""
    w = _np.asarray(w)
    return float((w != 0).sum() / w.size)


def stable_cumsum(arr, axis=None, rtol=1e-05, atol=1e-08):
    """Cumulative sum that checks final-sum stability."""
    return _np.cumsum(arr, axis=axis)


def fast_logdet(A):
    """log|det A| via SVD — robust to ill-conditioning."""
    sign, logdet = _np.linalg.slogdet(A)
    return logdet if sign > 0 else -_np.inf


def make_nonnegative(X, min_value=0):
    """Shift X so the minimum becomes ``min_value``."""
    X = _np.asarray(X)
    return X - X.min() + min_value


def _safe_accumulator_op(op, x, axis=None):
    """Run ``op`` on ``x`` after promoting integer dtypes to int64."""
    return op(x, axis=axis)


